package com.lexorion.payroll.api;
import static com.lexorion.payroll.api.PayRunDtos.*;import com.lexorion.payroll.domain.PayRunStatus;import com.lexorion.payroll.service.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payroll/pay-runs")@PreAuthorize("hasRole('ADMIN')")public class PayRunController{private final PayRunService service;private final PayRunProcessingService processing;private final PayRunPreparationService preparation;public PayRunController(PayRunService s,PayRunProcessingService p,PayRunPreparationService prep){service=s;processing=p;preparation=prep;}@GetMapping public PayRunPage list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction,@RequestParam(required=false)PayRunStatus status){return service.list(page,size,sort,direction,status);}@PostMapping public ResponseEntity<PayRunResponse>create(@Valid@RequestBody CreatePayRun r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/{payRunKey}")public PayRunResponse get(@PathVariable String payRunKey){return service.get(payRunKey);}@GetMapping("/{payRunKey}/employees")public List<PayRunEmployeeResponse>employees(@PathVariable String payRunKey){return service.employees(payRunKey);}@PostMapping("/{payRunKey}/employees")public ResponseEntity<PayRunEmployeeResponse>add(@PathVariable String payRunKey,@Valid@RequestBody AddPayRunEmployee r){return ResponseEntity.status(HttpStatus.CREATED).body(service.addEmployee(payRunKey,r));}@PostMapping("/{payRunKey}/process")public PayRunResponse process(@PathVariable String payRunKey){return processing.process(payRunKey);}@PostMapping("/{payRunKey}/recover")public PayRunResponse recover(@PathVariable String payRunKey){return processing.recover(payRunKey);}@PostMapping("/{payRunKey}/finalize")public PayRunResponse finalizeRun(@PathVariable String payRunKey){return service.finalizeRun(payRunKey);}@GetMapping("/{payRunKey}/preparation")public PayRunPreparationDtos.Preparation preparation(@PathVariable String payRunKey){return preparation.get(payRunKey);}@PutMapping("/{payRunKey}/preparation")public PayRunPreparationDtos.Preparation prepare(@PathVariable String payRunKey,@Valid@RequestBody PayRunPreparationDtos.Selection request){return preparation.save(payRunKey,request);}}
